-- Sistema de Gestión Integral de Capacitación: matriz, fechas y baja lógica de usuarios.
alter table public.profiles add column if not exists deleted_at timestamptz;
alter table public.profiles add column if not exists deleted_by uuid references public.profiles(id);

alter table public.training_needs add column if not exists planned_start_date date;
alter table public.training_needs add column if not exists planned_end_date date;
update public.training_needs
set planned_start_date = coalesce(planned_start_date, planned_date),
    planned_end_date = coalesce(planned_end_date, planned_date)
where planned_date is not null;
alter table public.training_needs drop constraint if exists internal_date_required;
alter table public.training_needs drop constraint if exists training_need_planned_dates;
alter table public.training_needs add constraint training_need_planned_dates check (
  (planned_start_date is null and planned_end_date is null)
  or (planned_start_date is not null and planned_end_date is not null and planned_end_date >= planned_start_date)
);
alter table public.training_needs add constraint internal_date_required check (
  type <> 'Interna' or (planned_start_date is not null and planned_end_date is not null)
);

create or replace function public.enforce_training_need_period()
returns trigger language plpgsql security definer set search_path=public as $$
declare selected_period public.planning_periods%rowtype;
begin
  select * into selected_period from public.planning_periods where id = new.period_id;
  if not found then raise exception 'El período seleccionado no existe.'; end if;
  if new.planned_start_date is not null and (new.planned_start_date < selected_period.start_date or new.planned_start_date > selected_period.end_date) then
    raise exception 'La fecha de inicio debe estar dentro del período %.', selected_period.name;
  end if;
  if new.planned_end_date is not null and (new.planned_end_date < selected_period.start_date or new.planned_end_date > selected_period.end_date) then
    raise exception 'La fecha de fin debe estar dentro del período %.', selected_period.name;
  end if;
  if new.planned_start_date is not null then
    new.planned_date := new.planned_start_date;
    new.quarter := 'Q' || ceil(extract(month from new.planned_start_date) / 3.0)::int;
  end if;
  return new;
end $$;
drop trigger if exists enforce_training_need_period_trigger on public.training_needs;
create trigger enforce_training_need_period_trigger before insert or update of period_id, planned_start_date, planned_end_date
on public.training_needs for each row execute function public.enforce_training_need_period();

create table if not exists public.competency_matrix (
  id uuid primary key default gen_random_uuid(),
  area text not null check (nullif(btrim(area), '') is not null),
  department text not null check (nullif(btrim(department), '') is not null),
  group_name text not null check (nullif(btrim(group_name), '') is not null),
  factor text not null check (nullif(btrim(factor), '') is not null),
  competency text not null check (nullif(btrim(competency), '') is not null),
  description text not null default '',
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references public.profiles(id) default auth.uid(),
  unique (department, factor, competency)
);
create index if not exists competency_matrix_lookup_idx on public.competency_matrix(department, factor, active);
alter table public.competency_matrix enable row level security;
drop policy if exists competency_matrix_read on public.competency_matrix;
create policy competency_matrix_read on public.competency_matrix for select to authenticated using (
  exists (select 1 from public.profiles p where p.id=auth.uid() and p.active and p.deleted_at is null)
  and (active or public.is_admin())
);
drop policy if exists competency_matrix_admin_write on public.competency_matrix;
create policy competency_matrix_admin_write on public.competency_matrix for all to authenticated using (public.is_admin()) with check (public.is_admin());
grant select, insert, update, delete on public.competency_matrix to authenticated;
drop trigger if exists audit_competency_matrix on public.competency_matrix;
create trigger audit_competency_matrix after insert or update or delete on public.competency_matrix
for each row execute function public.track_changes();

create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$
select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and active and deleted_at is null)
$$;
create or replace function public.can_view_training_need(p_area text,p_department text) returns boolean language sql stable security definer set search_path=public as $$
select exists(select 1 from public.profiles p where p.id=auth.uid() and p.active and p.deleted_at is null and (p.role='admin' or (p.can_view_entire_area and p.area=p_area) or p.department=p_department))
$$;
create or replace function public.can_use_training_structure(p_group text,p_area text,p_department text) returns boolean language sql stable security definer set search_path=public as $$
select exists(select 1 from public.profiles p where p.id=auth.uid() and p.active and p.deleted_at is null and (p.role='admin' or (p.occupational_group=p_group and p.area=p_area and p.department=p_department)))
$$;

-- La matriz institucional se inserta a continuación desde el archivo fuente validado.

on conflict (department,factor,competency) do update set
  area=excluded.area, group_name=excluded.group_name, description=excluded.description, active=true, updated_at=now();
